**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);
    int n = tab.size();

    int maxRozn = abs(tab[0] - tab[1]);
    int maxIdx = 0;
    for (int i = 1; i < n - 1; i++) {
        int r = abs(tab[i] - tab[i + 1]);
        if (r > maxRozn) {
            maxRozn = r;
            maxIdx = i;
        }
    }

    cout << "Najwieksza roznica sasiadow: |" << tab[maxIdx] << " - "
         << tab[maxIdx + 1] << "| = " << maxRozn << endl;
    cout << "Pozycje: " << maxIdx + 1 << " i " << maxIdx + 2 << endl;
    return 0;
}
```

**Wyjasnienie**: Iterujemy po parach sasiadow (i, i+1), obliczamy roznice bezwzgledna, sledzac maksimum. Zapamietujemy indeks pary.

Weryfikacja roznic bezwzglednych sasiadow:
- |25-30|=5, |30-12|=18, |12-48|=36, |48-5|=43, |5-39|=34, |39-41|=2, |41-10|=31, |10-33|=23, |33-18|=15, |18-50|=32, |50-47|=3
- Max: |48-5|=43 na pozycjach 4 i 5 (0-indeks: 3 i 4).
